  pendingTimeoutCompletion?: {
    expiresAtMs: number;
    settle: () => void;
  };
  /** False after the owning reply run commits a terminal outcome. */
  isAbortable?: (entry: ChatAbortControllerEntry) => boolean;
  /** Runs once when this registration is actually removed. */
  onRemoved?: () => void;
